function cleanupAudio(){recordGeneration++;recordPending=false;if(recorder?.state==='recording'){recorder.onstop=null;recorder.stop()}stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;clearTimeout(recordTimer);if(audioURL)URL.revokeObjectURL(audioURL);audioURL=null}
function go(id){if(!['practica','banco','cuaderno','progreso','guia'].includes(id))id='practica';if(id!=='practica')cleanupAudio();if('speechSynthesis'in window)speechSynthesis.cancel();$$('.page').forEach(p=>p.hidden=p.id!==id);$$('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===id);if(b.dataset.page===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(id==='banco')renderBank();if(id==='cuaderno')requestAnimationFrame(draw);if(id==='progreso')renderProgress();if(id==='practica')renderActivity();history.replaceState(null,'','#'+id);$('#main').focus({preventScroll:true});window.scrollTo(0,0)}
