function choose(word){cleanupAudio();current=CURATED.find(x=>x.word===word)||{word,emoji:'✦',meaning:'Palabra del banco. Podés practicarla con una persona que modele su pronunciación.',group:'banco'};$('#currentWord').textContent=current.word;$('#wordEmoji').textContent=current.emoji;$('#syllables').textContent=current.syllables?current.syllables.replaceAll('-',' · '):'Modelo de escritura';$('#wordMeaning').textContent=current.meaning;$('#wordTag').textContent=({rr:'R FUERTE',r:'R SUAVE',l:'SONIDO L',s:'SONIDO S',grupos:'GRUPOS CONSONÁNTICOS',banco:'BANCO DE PALABRAS'})[current.group]||(current.region==='ar'?'USO ARGENTINO':'PALABRA COTIDIANA');updateFavorite();$('#traceText').value=current.word.slice(0,24);strokes=[];$('#traceKeyboard').value='';$('#traceFeedback').textContent='';renderActivity()}
