$('#favorite').onclick=()=>{const i=state.favorites.indexOf(current.word);if(i<0)state.favorites.push(current.word);else state.favorites.splice(i,1);save();updateFavorite()};
function next(){let group=$('#focus').value,max=Number($('#level').value),pool=group==='favoritos'?state.favorites:CURATED.filter(w=>group==='todos'||(group==='argentina'?w.region==='ar':w.group===group)).map(w=>w.word);pool=pool.filter(w=>(!max||w.length<=max)&&w!==current.word);if(!pool.length){toast('No hay otra palabra con esta combinación. Cambiá el filtro o agregá favoritas.');return}choose(pool[Math.floor(Math.random()*pool.length)])}
$('#nextWord').onclick=next;$('#focus').onchange=next;$('#level').onchange=next;$('#speed').oninput=()=>$('#speedValue').textContent=$('#speed').value+'×';
function loadVoices(){const old=$('#voice').value;voices='speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>/^es(?:-|_)/i.test(v.lang)&&(!$('#localVoice').checked||v.localService)):[];voices.sort((a,b)=>Number(/^es[-_]AR$/i.test(b.lang))-Number(/^es[-_]AR$/i.test(a.lang)));$('#voice').replaceChildren();for(const [i,v]of voices.entries()){const o=document.createElement('option');o.value=i;o.textContent=`${v.name} · ${v.lang}${v.localService?' · local':' · servicio remoto'}`;$('#voice').append(o)}if(!voices.length){const o=document.createElement('option');o.textContent='Sin voz española disponible';$('#voice').append(o)}else if(voices[old])$('#voice').value=old;$('#voiceStatus').textContent=voices.length?'Podés escuchar palabras con la voz elegida. Si no es es-AR, su acento puede diferir.':'No hay una voz española compatible con el filtro. Instalá una voz en el dispositivo o usá el modelo de un acompañante.'}
if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=loadVoices;$('#localVoice').onchange=loadVoices;
function speak(text){if(!voices.length){toast('No hay voz española disponible. Revisá Guía y ajustes.');return false}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=voices[Number($('#voice').value)]||voices[0];u.lang=u.voice.lang;u.rate=Number($('#speed').value);u.onerror=e=>{if(e.error!=='interrupted'&&e.error!=='canceled')toast('La voz no pudo reproducirse. Revisá las voces instaladas.')};speechSynthesis.speak(u);return true}
$('#listen').onclick=()=>speak(current.word);
$$('[data-mode]').forEach(b=>b.onclick=()=>{cleanupAudio();mode=b.dataset.mode;renderActivity()});
function renderActivity(){ $('#currentWord').style.visibility='';$('#syllables').style.visibility=''; $$('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.mode===mode));$('#activity').replaceChildren();if(mode==='hablar'){$('#activity').innerHTML='<h3>Escuchá. Probá. Volvé a escuchar.</h3><p>Decí la palabra a tu ritmo. Si querés, grabate y compará con un acompañante.</p><div class="inline"><button id="recordAudio">● Grabar mi voz</button><button id="doneSpeak">Ya practiqué ✓</button><button id="toTrace">✎ Trazar palabra</button></div><p id="recordStatus" role="status" class="muted">Audio temporal, solo en este dispositivo. Máximo 30 segundos.</p><audio id="playback" controls hidden></audio><button id="downloadAudio" hidden>Descargar audio</button>';$('#recordAudio').onclick=toggleRecording;$('#doneSpeak').onclick=()=>record('Pronunciación');$('#toTrace').onclick=()=>go('cuaderno')}
else if(mode==='escribir'){$('#activity').innerHTML='<h3>De la palabra al papel.</h3><div class="inline"><button id="hideModel" aria-pressed="false">Ocultar modelo</button><button id="dictate">♪ Escuchar dictado</button></div><form id="spellingForm"><label>Escribí la palabra<input id="spelling" autocomplete="off" spellcheck="false" autocapitalize="none" maxlength="100"></label><button class="primary">Comparar escritura</button></form><p id="spellFeedback" role="status"></p>';$('#hideModel').onclick=()=>{let hidden=$('#currentWord').style.visibility!=='hidden';$('#currentWord').style.visibility=hidden?'hidden':'';$('#syllables').style.visibility=hidden?'hidden':'';$('#hideModel').textContent=hidden?'Mostrar modelo':'Ocultar modelo';$('#hideModel').setAttribute('aria-pressed',hidden)};$('#dictate').onclick=()=>speak(current.word);$('#spellingForm').onsubmit=e=>{e.preventDefault();let input=$('#spelling').value;$('#spellFeedback').textContent=C.spelling(input,current.word);if(C.normalize(input)===C.normalize(current.word)){record('Escritura');$('#spellingForm button').disabled=true}};$('#spelling').oninput=()=>$('#spellingForm button').disabled=false}
else{renderPair()}
if(mode!=='escribir'){$('#currentWord').style.visibility='';$('#syllables').style.visibility=''}}
let pairIndex=0,pairTarget=0,pairHeard=false;
function renderPair(){const pair=PAIRS[pairIndex];pairTarget=Math.floor(Math.random()*2);pairHeard=false;$('#activity').innerHTML='<h3>¿Qué palabra escuchaste?</h3><p id="pairLabel"></p><button id="playPair" class="primary">♪ Escuchar una palabra</button><div id="pairChoices" class="pair-buttons inline"></div><p id="pairFeedback" role="status"></p><button id="nextPair">Otro par →</button>';$('#pairLabel').textContent=pair[2]+'. Escuchá y elegí.';for(const [i,w]of pair.slice(0,2).entries()){const b=document.createElement('button');b.textContent=w;b.onclick=()=>{if(!pairHeard){$('#pairFeedback').textContent='Primero escuchá la palabra. Si no hay voz disponible, practicá ambos modelos con un acompañante.';return}$('#pairFeedback').textContent=i===pairTarget?'¡Esa es la palabra que sonó!':'Escuchá otra vez y compará los sonidos.';if(i===pairTarget){record('Escucha de pares',w);$$('#pairChoices button').forEach(x=>x.disabled=true)}};$('#pairChoices').append(b)}$('#playPair').onclick=()=>pairHeard=speak(pair[pairTarget]);$('#nextPair').onclick=()=>{pairIndex=(pairIndex+1)%PAIRS.length;renderPair()}}
async function toggleRecording(){if(recorder?.state==='recording'){recorder.stop();return}if(recordPending)return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('Este navegador o dirección no admite grabación. Usá localhost o HTTPS.');return}cleanupAudio();const gen=recordGeneration;recordPending=true;$('#recordAudio').disabled=true;$('#recordStatus').textContent='Esperando permiso del micrófono…';try{const acquired=await navigator.mediaDevices.getUserMedia({audio:true});if(gen!==recordGeneration){acquired.getTracks().forEach(t=>t.stop());return}stream=acquired;recorder=new MediaRecorder(stream);let chunks=[];recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{clearTimeout(recordTimer);stream?.getTracks().forEach(t=>t.stop());stream=null;const blob=new Blob(chunks,{type:recorder.mimeType});audioURL=URL.createObjectURL(blob);$('#playback').src=audioURL;$('#playback').hidden=false;$('#downloadAudio').hidden=false;$('#downloadAudio').onclick=()=>download('mi-practica.'+(blob.type.includes('mp4')?'m4a':'webm'),blob);$('#recordAudio').textContent='● Grabar otra vez';$('#recordStatus').textContent='Escuchá tu grabación. No se evalúa automáticamente la pronunciación.'};recorder.start();$('#recordAudio').disabled=false;$('#recordAudio').textContent='■ Detener grabación';$('#recordStatus').textContent='Grabando… se detiene a los 30 segundos.';recordTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},30000)}catch{if(gen===recordGeneration){$('#recordStatus').textContent='No se pudo acceder al micrófono. Revisá el permiso del navegador o continuá sin grabarte.';$('#recordAudio').disabled=false}stream?.getTracks().forEach(t=>t.stop())}finally{recordPending=false}}
function bankBase(){return ({curated:CURATED.map(x=>x.word),ar:CURATED.filter(x=>x.region==='ar').map(x=>x.word),fav:state.favorites,custom:state.custom})[$('#source').value]||allWords}
function renderBank(){const results=C.filterWords(bankBase(),$('#search').value,$('#contains').value),pages=Math.max(1,Math.ceil(results.length/48));page=Math.min(page,pages-1);$('#bankCount').textContent=`${results.length.toLocaleString('es-AR')} palabras · ${allWords.length.toLocaleString('es-AR')} en el banco instalado`;$('#wordList').replaceChildren();for(const w of results.slice(page*48,page*48+48)){const b=document.createElement('button');b.textContent=w;b.onclick=()=>{choose(w);go('practica')};$('#wordList').append(b)}if(!results.length)$('#wordList').textContent='No hay coincidencias. Podés agregar la palabra abajo.';$('#pageNumber').textContent=`Página ${page+1} de ${pages}`;$('#prevPage').disabled=page===0;$('#nextPage').disabled=page===pages-1}
for(const id of ['search','contains','source'])$('#'+id).addEventListener(id==='source'?'change':'input',()=>{page=0;renderBank()});$('#prevPage').onclick=()=>{page--;renderBank()};$('#nextPage').onclick=()=>{page++;renderBank()};
function addWords(words){const old=state.custom.length;state.custom=[...new Set([...state.custom,...words])].slice(0,50000);allWords=[...new Set([...allWords,...state.custom])].sort((a,b)=>a.localeCompare(b,'es'));save();renderBank();return state.custom.length-old}
$('#addForm').onsubmit=e=>{e.preventDefault();const w=C.normalize($('#newWord').value);if(!C.validWord(w)){toast('Usá letras españolas, espacios o guiones; hasta 50 caracteres.');return}addWords([w]);$('#newWord').value='';toast('Palabra guardada en este navegador.')};$('#importWords').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>2*1024*1024){$('#importStatus').textContent='El archivo supera 2 MB.';return}try{const words=C.parseList(await f.text()),count=addWords(words);$('#importStatus').textContent=`${count} palabras agregadas. Se omiten duplicados, líneas inválidas y entradas que superen el límite de 50.000 palabras propias.`}catch{$('#importStatus').textContent='No se pudo leer el archivo.'}e.target.value=''};
function renderProgress(){$('#stats').replaceChildren();for(const [n,label]of [[state.history.length,'actividades registradas'],[new Set(state.history.map(x=>x.word)).size,'palabras exploradas'],[state.favorites.length,'palabras favoritas']]){const d=document.createElement('div');d.className='card';const s=document.createElement('strong');s.textContent=n;const p=document.createElement('p');p.textContent=label;d.append(s,p);$('#stats').append(d)}$('#history').replaceChildren();if(!state.history.length)$('#history').textContent='Tu recorrido empieza con la primera práctica.';for(const x of state.history.slice(-30).reverse()){const d=document.createElement('div');d.className='history-row';const strong=document.createElement('strong');strong.textContent=x.word+' · '+x.kind;const span=document.createElement('span');span.textContent=new Date(x.at).toLocaleString('es-AR');d.append(strong,span);$('#history').append(d)}}
$('#exportProgress').onclick=()=>download('habla-registro.json',new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),...state},null,2)],{type:'application/json'}));$('#clearProgress').onclick=()=>$('#deleteConfirm').hidden=false;$('#cancelDelete').onclick=()=>$('#deleteConfirm').hidden=true;$('#confirmDelete').onclick=()=>{state.history=[];save();renderProgress();$('#deleteConfirm').hidden=true;toast('Registro borrado.')};
const canvas=$('#canvas'),ctx=canvas.getContext('2d');
function draw(){if($('#cuaderno').hidden)return;let rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);let w=rect.width,h=rect.height;ctx.fillStyle='#fffdf8';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#dce3db';ctx.lineWidth=1;for(let y of [h*.25,h*.52,h*.78]){ctx.setLineDash(y===h*.52?[5,6]:[]);ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.setLineDash([]);let text=$('#traceText').value,style=$('#letterStyle').value;if(style==='upper')text=text.toLocaleUpperCase('es');else text=text.toLocaleLowerCase('es');let family=style==='cursive'?'cursive':'Arial',size=Math.min(110,h*.4);ctx.font=`${size}px ${family}`;while(ctx.measureText(text).width>w-35&&size>14){size-=2;ctx.font=`${size}px ${family}`}ctx.fillStyle='#b6c5b8';ctx.fillText(text,18,h*.73);ctx.lineCap='round';ctx.lineJoin='round';for(const s of strokes){ctx.strokeStyle='#245c50';ctx.lineWidth=s.width;ctx.beginPath();s.points.forEach((p,i)=>{if(i)ctx.lineTo(p[0]*w,p[1]*h);else ctx.moveTo(p[0]*w,p[1]*h)});if(s.points.length===1){const p=s.points[0];ctx.lineTo(p[0]*w+.1,p[1]*h+.1)}ctx.stroke()}}
function point(e){const r=canvas.getBoundingClientRect();return [(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height]}
canvas.onpointerdown=e=>{if(pointer!==null||e.button>0)return;pointer=e.pointerId;canvas.setPointerCapture(pointer);activeStroke={width:Number($('#penSize').value),points:[point(e)]};strokes.push(activeStroke);draw()};canvas.onpointermove=e=>{if(pointer!==e.pointerId||!activeStroke)return;activeStroke.points.push(point(e));draw()};function endPointer(e){if(pointer===e.pointerId){pointer=null;activeStroke=null}}canvas.onpointerup=endPointer;canvas.onpointercancel=endPointer;canvas.onlostpointercapture=endPointer;
new ResizeObserver(()=>draw()).observe(canvas);for(const id of ['traceText','letterStyle'])$('#'+id).addEventListener('input',()=>{strokes=[];$('#traceKeyboard').value='';$('#traceFeedback').textContent='';draw()});$('#undo').onclick=()=>{strokes.pop();draw()};$('#clearCanvas').onclick=()=>{strokes=[];draw()};$('#saveDrawing').onclick=()=>canvas.toBlob(blob=>{if(blob)download('habla-caligrafia.png',blob)});$('#traceKeyboard').oninput=()=>$('#traceFeedback').textContent=C.spelling($('#traceKeyboard').value,$('#traceText').value);$('#doneTrace').onclick=()=>{if(!$('#traceText').value.trim()){toast('Escribí un modelo antes de registrar la práctica.');return}record('Caligrafía',$('#traceText').value)};
